## Why This Is Asked
Tests practical CGOA memory ownership and error propagation with a non-trivial parser and a streaming Go consumer.

## Key Concepts
- CGO memory ownership across boundaries
- Safe conversion of C strings to Go strings
- Properly freeing C-allocated memory
- Basic tokenizer with quotes/escapes

## Code Example
```c
// header: tokenizer.h
int tokenize_line(const char* line, char*** tokens, size_t* n);
void free_tokens(char** tokens, size_t n);
```
```c
#include <stdlib.h>
#include <string.h>
#include <tokenizer.h>

int tokenize_line(const char* line, char*** tokens, size_t* n){
  if(!line) return -1;
  const char* p = line;
  size_t cap = 8, i = 0;
  char** toks = (char**)malloc(cap*sizeof(char*));
  while(*p){
    while(*p==' ') p++;
    if(!*p) break;
    const char* start = p;
    int inq = 0;
    while(*p){
      if(*p=='"') inq = !inq;
      else if(*p==' ' && !inq) break;
      p++;
    }
    size_t len = p-start;
    char* t = (char*)malloc(len+1);
    memcpy(t, start, len);
    t[len] = '\0';
    if(i==cap){ cap*=2; toks=(char**)realloc(toks, cap*sizeof(char*)); }
    toks[i++] = t;
  }
  *tokens = toks; *n = i; return 0;
}

void free_tokens(char** tokens, size_t n){
  if(!tokens) return; for(size_t i=0;i<n;i++){ free(tokens[i]); } free(tokens);
}
```
```go
package tokenizer
/*
#include <tokenizer.h>
#include <stdlib.h>
*/
import "C"
import (
  "errors"
  "unsafe"
)

func TokenizeLine(line string) ([]string, error) {
  cLine := C.CString(line)
  defer C.free(unsafe.Pointer(cLine))
  var cTokens **C.char
  var n C.size_t
  if code := C.tokenize_line(cLine, &cTokens, &n); code != 0 {
    return nil, errors.New("tokenization failed")
  }
  count := int(n)
  toks := make([]string, 0, count)
  slice := (*[1<<30]*C.char)(unsafe.Pointer(cTokens))[:count:count]
  for _, cstr := range slice {
    toks = append(toks, C.GoString(cstr))
  }
  C.free_tokens(cTokens, n)
  return toks, nil
}
```
```go
package main
import (
  "bufio"
  "fmt"
  "os"
  "sync/atomic"
  t "./tokenizer"
)
func main(){
  in := bufio.NewScanner(os.Stdin)
  var total, lines uint64
  for in.Scan(){
    line := in.Text()
    tokens, err := t.TokenizeLine(line)
    if err != nil { fmt.Println("err:", err); continue }
    atomic.AddUint64(&lines, 1)
    atomic.AddUint64(&total, uint64(len(tokens)))
    fmt.Println(tokens)
  }
}
```

